const categorias = [
  'PRECIO',
  'STOCK',
  'CARACTERISTICAS',
  'RECOMENDACION',
  'OPERACION_NO_PERMITIDA',
  'OTROS',
];

const fallback =
  'No pude procesar tu consulta en este momento. ' +
  'Por favor, intenta nuevamente en unos minutos.';

try {
  const data = JSON.parse($json.output);

  if (
    data === null ||
    typeof data !== 'object' ||
    Array.isArray(data) ||
    !categorias.includes(data.clasificacion) ||
    typeof data.respuesta !== 'string' ||
    !data.respuesta.trim()
  ) {
    return {
      json: {
        text: fallback,
        valid: false,
        clasificacion: null,
        error_type: 'INVALID_SCHEMA',
        error_detail: 'La respuesta no cumple el contrato esperado',
      },
    };
  }

  return {
    json: {
      text: data.respuesta.trim().replace(/\*\*(.+?)\*\*/g, '*$1*'),
      valid: true,
      clasificacion: data.clasificacion,
      error_type: null,
      error_detail: null,
    },
  };

} catch (error) {
  return {
    json: {
      text: fallback,
      valid: false,
      clasificacion: null,
      error_type: 'INVALID_JSON',
      error_detail: error.message,
    },
  };
}
